const schema = [{"@context":"https://schema.org","@type":"Service","name":"Visual &amp; accessibility editing","serviceType":"Editorial service","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/academic-editorial-services/visual-and-accessibility-editing-services/","description":"Figures, tables, layouts and PDFs edited to global accessibility standards — alt text, colour contrast, heading hierarchy and tagged PDFs.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Why does my manuscript need visual and accessibility editing?","acceptedAnswer":{"@type":"Answer","text":"Most journals and academic platforms now require accessible content at submission, and several check it automatically on upload. Poorly structured visuals, low-contrast figures, missing alt text and inaccessible tables cause delays and rejections.\n\nThe reason it catches people out is that none of it is visible in a language edit. A manuscript can be perfectly written, fully copyedited, and still fail the check."}},{"@type":"Question","name":"What materials do you edit for accessibility?","acceptedAnswer":{"@type":"Answer","text":"Research manuscripts, theses, dissertations, figures, diagrams, graphs, data visualisations, tables, infographics, posters, presentations and supplementary files, along with educational and technical documents.\n\nFor e-learning and course material we usually build a style guide alongside the edit, because that work recurs and the second batch should not cost what the first did."}},{"@type":"Question","name":"Which accessibility standards do you follow?","acceptedAnswer":{"@type":"Answer","text":"WCAG 2.1 and 2.2, Section 508, ADA guidance, the European EN 301 549, and PDF/UA (ISO 14289-1) for tagged PDFs. Publisher-specific requirements sit on top of whichever of those governs your document.\n\nThe order names the standard, the version and the level, because “accessible” on its own is not something anybody can check."}},{"@type":"Question","name":"Do you write alt text for images and figures?","acceptedAnswer":{"@type":"Answer","text":"Yes, and it is the part that most rewards a subject-matter editor. Alt text for a scientific figure has to say what the figure shows — the direction of the effect, where the curves separate, what the axes measure — not that a graph is present.\n\nComplex figures get a short alt text plus a long description, so a reader can get the gist quickly and the detail if they want it."}},{"@type":"Question","name":"Do you ensure publisher compliance as well?","acceptedAnswer":{"@type":"Answer","text":"Yes. Documents are worked to the required publisher or journal guidelines — formatting, figure specification, accessibility expectations and layout consistency.\n\nIt matters that these are done together. The publisher’s figure specification and the accessibility standard regularly disagree, and resolving that after the fact means redoing the figures."}},{"@type":"Question","name":"Can you work from a PDF?","acceptedAnswer":{"@type":"Answer","text":"We can, but it costs more and the result is weaker. Alt text, tagging and reading order live in the document structure, and exporting to PDF throws most of that away — rebuilding it is slower than doing it once from the original.\n\nSend editable source files wherever you have them. Where the PDF genuinely is the only version left, say so and we will quote the remediation honestly."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Services","item":"https://pubrica.com/services/"},{"@type":"ListItem","position":3,"name":"Academic editorial","item":"https://pubrica.com/services/academic-editorial-services/visual-and-accessibility-editing-services/"}]}];

